// codec is what every generated XDR type offers.
type codec interface {
	xdr.DecoderFrom
	MarshalBinary() ([]byte, error)
	UnmarshalBinary([]byte) error
}

// types is the registry of XDR types the driver decodes by name: the types the corpus and the conformance
