var typesByLower = func() map[string]string {
	m := map[string]string{}
	for k := range types {
		m[strings.ToLower(k)] = k
	}
	return m
}()

func typeNames() []string {
	names := make([]string, 0, len(types))
	for k := range types {
		names = append(names, k)
	}
	sort.Strings(names)
	return names
}

// newValue returns a fresh value of the named XDR type and its Go name.
func newValue(name string) (codec, string, bool) {
	goName, found := typesByLower[strings.ToLower(name)]
	if !found {
		return nil, "", false
	}
	return types[goName](), goName, true
}

// schemaProbes evaluates the protocol capability probes against the SDK's generated enums.
func schemaProbes() map[string]bool {
	return map[string]bool{
		"sc_address_type_muxed_contract": xdr.ScAddressType(0).ValidEnum(5),
		"stellar_value_signed_ms":        xdr.StellarValueType(0).ValidEnum(3),
	}
}

// knownProtocol is the newest protocol whose definitions the probes and the ceiling below describe.
const knownProtocol = 30 // pin:protocol.max_supported

// ceiling is the highest member of each sentinel enum in the pinned definitions. A protocol nearly always adds
// a member to one of them, so an SDK that declares a member above one carries newer XDR than this driver can
// bound. The values are generated from the XDR definitions (`make xdr-ceilings`; `make test` fails when they
// drift); add or remove an enum by hand, never edit a value.
var ceiling = []struct {
	name  string
	max   int32
	valid func(int32) bool
}{
	// BEGIN generated: xdrcheck xdr ceilings (stellar-xdr v30.0)
	{"ContractCostType", 94, xdr.ContractCostType(0).ValidEnum},
	{"ConfigSettingId", 20, xdr.ConfigSettingId(0).ValidEnum},
	{"ContractExecutableType", 2, xdr.ContractExecutableType(0).ValidEnum},
	{"EnvelopeType", 10, xdr.EnvelopeType(0).ValidEnum},
	{"HostFunctionType", 3, xdr.HostFunctionType(0).ValidEnum},
	{"LedgerEntryType", 9, xdr.LedgerEntryType(0).ValidEnum},
	{"LedgerUpgradeType", 7, xdr.LedgerUpgradeType(0).ValidEnum},
	{"OperationType", 26, xdr.OperationType(0).ValidEnum},
	{"ScAddressType", 5, xdr.ScAddressType(0).ValidEnum},
	{"ScValType", 22, xdr.ScValType(0).ValidEnum},
	{"StellarValueType", 4, xdr.StellarValueType(0).ValidEnum},
	// END generated: xdrcheck xdr ceilings
}

// beyondKnown lists the sentinel enums the SDK declares a member above the Protocol 30 ceiling in. The
// generated Go enums can only be asked about one value at a time, so the 32 values above each ceiling are
// asked; XDR enums are numbered without such gaps.
func beyondKnown() []string {
	var out []string
	for _, c := range ceiling {
		for v := c.max + 1; v <= c.max+32; v++ {
			if c.valid(v) {
				out = append(out, fmt.Sprintf("%s %d", c.name, v))
				break
			}
		}
	}
	return out
}

// probeProtocol is the protocol that introduced each probed feature; a probe not listed is a knownProtocol one.
var probeProtocol = map[string]int{"sc_address_type_muxed_contract": 30, "stellar_value_signed_ms": 30}

// schemaProtocol is the xdr_schema.protocol the driver reports: the highest protocol it can prove the SDK's
// XDR reaches. knownProtocol when every probe passes, else the protocol before the oldest feature whose probe
// fails; none (false) when the SDK declares enum members above the Protocol 30 ceiling: its XDR is newer than
// the probes, and a reported knownProtocol would excuse its refusals of newer variants.
func schemaProtocol(probes map[string]bool, beyond []string) (int, bool) {
	if len(beyond) > 0 {
		return 0, false
	}
	p := knownProtocol
	for name, ok := range probes {
		introduced, listed := probeProtocol[name]
		if !listed {
			introduced = knownProtocol
		}
		if !ok && introduced-1 < p {
			p = introduced - 1
		}
	}
	return p, true
}

// defaultDepth is the decode depth the SDK's SafeUnmarshal uses, from the go-xdr version the SDK pins.
func defaultDepth() int { return xdr3.DecodeDefaultMaxDepth }

// readInput returns the bytes of an xdr input: the file or the inline hex, and for a record-marked file the
// requested frame, split with the SDK's own frame reader.
func readInput(in *input) ([]byte, error) {
	var raw []byte
	switch {
	case in.XDRHex != nil:
		b, err := hex.DecodeString(*in.XDRHex)
		if err != nil {
			return nil, fmt.Errorf("xdr_hex: %w", err)
		}
		raw = b
	case in.Path != "":
		b, err := os.ReadFile(in.Path)
		if err != nil {
			return nil, err
		}
		raw = b
	default:
		return nil, errors.New("the xdr input has neither path nor xdr_hex")
	}
	if in.Framing != "record-marked" {
		return raw, nil
	}
	r := bytes.NewReader(raw)
	for i := 0; ; i++ {
		n, err := xdr.ReadFrameLength(r)
		if err != nil {
			return nil, fmt.Errorf("frame %d: %w", i, err)
		}
		if int64(n) > int64(r.Len()) {
			return nil, fmt.Errorf("frame %d: record mark says %d bytes, %d remain", i, n, r.Len())
		}
		frame := make([]byte, n)
		if _, err := io.ReadFull(r, frame); err != nil {
			return nil, fmt.Errorf("frame %d: %w", i, err)
		}
		if i == in.FrameIndex {
			return frame, nil
		}
	}
}

// decodeStrict decodes raw as the named type with the SDK's strict entry point. It returns the value, or a
// reject result.
func decodeStrict(name string, raw []byte) (codec, *result) {
	v, goName, found := newValue(name)
	if !found {
		r := notApplicable("type_not_generated", "the driver does not decode "+name)
		return nil, &r
	}
	if err := xdr.SafeUnmarshal(raw, v); err != nil {
		r := reject(classifyDecode(err, len(raw), goName), "xdr.SafeUnmarshal("+goName+")", err)
		return nil, &r
	}
	// SafeUnmarshal checks that every byte was consumed; the driver checks again with the decoder that
	// reports the count, so a decoder that stopped early can never pass as a complete decode.
	fresh, _, _ := newValue(name)
	n, err := xdr.NewBytesDecoder().DecodeBytes(fresh, raw)
	if err == nil && n != len(raw) {
		err = fmt.Errorf("consumed %d of %d bytes", n, len(raw))
	}
	if err != nil {
		r := reject("trailing_bytes", "xdrcheck-driver-go consumed-length check", err)
		return nil, &r
	}
	return v, nil
}

// levelCodec is L0: strict decode, consumed-length check, re-encode, and the lenient entry point.
func levelCodec(name string, raw []byte) result {
	v, rej := decodeStrict(name, raw)
	lenient := lenientEntryPoint(name, raw, rej == nil)
	if rej != nil {
		if lenient != nil {
			rej.Actual = map[string]any{"lenient_entry_points": lenient}
		}
		return *rej
	}
	out, err := v.MarshalBinary()
	if err != nil {
		return reject("other", "MarshalBinary", err)
	}
	sum := sha256.Sum256(out)
	actual := map[string]any{"consumed_bytes": len(raw), "reencoded_sha256": hex.EncodeToString(sum[:])}
	if lenient != nil {
		actual["lenient_entry_points"] = lenient
	}
	if !bytes.Equal(out, raw) {
		if len(out) <= 4096 {
			actual["reencoded_hex"] = hex.EncodeToString(out)
		}
		return result{Outcome: "diverge", Reason: &reason{Code: "reencode_mismatch", EntryPoint: "MarshalBinary"}, Actual: actual}
	}
	return ok(actual)
}

// lenientEntryPoint runs the generated UnmarshalBinary, which does not check that the input was consumed, and
// reports it when it disagrees with the strict entry point.
func lenientEntryPoint(name string, raw []byte, strictAccepted bool) []map[string]any {
	v, goName, found := newValue(name)
	if !found {
		return nil
	}
	err := v.UnmarshalBinary(raw)
	if (err == nil) == strictAccepted {
		return nil
	}
	e := map[string]any{"entry_point": goName + ".UnmarshalBinary", "accepted": err == nil}
	if err == nil {
		fresh, _, _ := newValue(name)
		if n, derr := xdr.NewBytesDecoder().DecodeBytes(fresh, raw); derr == nil && n < len(raw) {
			e["note"] = fmt.Sprintf("accepted with %d trailing bytes (consumed %d of %d)", len(raw)-n, n, len(raw))
		}
	} else {
		e["note"] = trim(err.Error())
	}
	return []map[string]any{e}
}

var (
	enumRe     = regexp.MustCompile(`'(-?\d+)' is not a valid (\w+) enum value`)
	sliceLenRe = regexp.MustCompile(`max slice limit - read: '(\d+)'`)
	labelRe    = regexp.MustCompile(`decoding ([\w\[\]]+): `)
)

// classifyDecode maps a go-xdr / generated-code decode error to a reason code. The SDK's errors carry no
// types beyond the depth sentinel, so the mapping reads the message; the message itself is reported too.
// topType is the Go name of the type decoded, the implicit outermost label of the error chain.
func classifyDecode(err error, inputLen int, topType string) string {
	msg := err.Error()
	labels := [][]string{{"", topType}}
	labels = append(labels, labelRe.FindAllStringSubmatch(msg, -1)...)
	lastLabel := labels[len(labels)-1][1]
	switch {
	case errors.Is(err, xdr.ErrMaxDecodingDepthReached), strings.Contains(msg, "maximum decoding depth reached"):
		return "depth"
	case strings.Contains(msg, "input not fully consumed"):
		return "trailing_bytes"
	case strings.Contains(msg, "non-zero padding"):
		return "nonzero_padding"
	case strings.Contains(msg, "bool not 0 or 1"):
		// A bool field is decoded under its own label; an optional's presence flag under the label of the
		// type it guards.
		if lastLabel == "Bool" || lastLabel == "bool" {
			return "bool_range"
		}
		return "optional_flag_range"
	case strings.Contains(msg, "switch value"):
		return "union_arm_undeclared"
	case enumRe.MatchString(msg):
		m := enumRe.FindStringSubmatch(msg)
		if len(labels) >= 2 && isDiscriminant(labels[len(labels)-2][1], m[2]) {
			return "union_arm_undeclared"
		}
		return "enum_undeclared"
	case strings.Contains(msg, "exceeds remaining input length"):
		return "length_exceeds_input"
	case strings.Contains(msg, "exceeds size limit"):
		return "length_exceeds_max"
	case sliceLenRe.MatchString(msg):
		// go-xdr bounds a length by min(schema maximum, remaining input) and reports both the same way.
		n, _ := strconv.ParseInt(sliceLenRe.FindStringSubmatch(msg)[1], 10, 64)
		if n > int64(inputLen) {
			return "length_exceeds_input"
		}
		return "length_exceeds_max"
	case strings.Contains(msg, "EOF"):
		return "length_exceeds_input"
	}
	return "decode_error"
}

// discriminants maps a union's Go type name to its discriminant's Go type name, for every union reachable
// from the registry.
var discriminants = func() map[string]string {
	out := map[string]string{}
	seen := map[reflect.Type]bool{}
	var walk func(t reflect.Type)
	walk = func(t reflect.Type) {
		for t.Kind() == reflect.Pointer || t.Kind() == reflect.Slice || t.Kind() == reflect.Array {
			t = t.Elem()
		}
		if t.Kind() != reflect.Struct || seen[t] {
			return
		}
		seen[t] = true
		if sw, isUnion := reflect.Zero(t).Interface().(interface{ SwitchFieldName() string }); isUnion {
			if f, found := t.FieldByName(sw.SwitchFieldName()); found {
				out[t.Name()] = f.Type.Name()
			}
		}
		for i := 0; i < t.NumField(); i++ {
			walk(t.Field(i).Type)
		}
	}
	for _, mk := range types {
		walk(reflect.TypeOf(mk()))
	}
	return out
}()

func isDiscriminant(container, enum string) bool { return discriminants[container] == enum }
